        </style>

        <div class="st-summary-glass-card">
            <div class="st-summary-header">
                <span class="st-summary-icon">💙</span>
                <span>剧情摘要</span>
            </div>
            <div class="st-summary-content">
                <div class="st-summary-item">
                    <span class="st-summary-label">[时间]</span>
                    <span class="st-summary-value st-val-time"></span>
                </div>
                <div class="st-summary-item">
                    <span class="st-summary-label">[地点]</span>
                    <span class="st-summary-value st-val-location"></span>
                </div>
                <div class="st-summary-item">
                    <span class="st-summary-label">[在场]</span>
                    <span class="st-summary-value st-val-present"></span>
                </div>
                <div class="st-summary-item full-width">
                    <span class="st-summary-label">[互动]</span>
                    <span class="st-summary-value st-val-interaction"></span>
                </div>
                <div class="st-summary-item full-width">
                    <span class="st-summary-label">[事件]</span>
                    <span class="st-summary-value st-val-event"></span>
                </div>
            </div>
        </div>

        <script>
            (function() {
                const container = document.currentScript.parentElement;
                const rawData = container.querySelector('.sys-data-source').innerText;

                function sanitizeCoT(text) {
                    if (!text) return '';
                    return text.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '').trim();
                }

                function parseSummary(text) {
                    const cleanText = sanitizeCoT(text);
                    const result = {
                        time: '暂无',
                        location: '暂无',
                        present: '暂无',
                        interaction: '暂无',
                        event: '暂无'
                    };

                    const timeMatch = cleanText.match(/\[时间\|([\s\S]*?)\]/i);
                    if (timeMatch && timeMatch[1].trim()) result.time = timeMatch[1].trim();

                    const locMatch = cleanText.match(/\[地点\|([\s\S]*?)\]/i);
                    if (locMatch && locMatch[1].trim()) result.location = locMatch[1].trim();

                    const presentMatch = cleanText.match(/\[在场\|([\s\S]*?)\]/i);
                    if (presentMatch && presentMatch[1].trim()) result.present = presentMatch[1].trim();

                    const intMatch = cleanText.match(/\[互动\|([\s\S]*?)\]/i);
                    if (intMatch && intMatch[1].trim()) result.interaction = intMatch[1].trim();

                    const eventMatch = cleanText.match(/\[事件\|([\s\S]*?)\]/i);
                    if (eventMatch && eventMatch[1].trim()) result.event = eventMatch[1].trim();

                    return result;
                }

                const data = parseSummary(rawData);
                const charName = "{{char}}";

                function highlightChar(text) {
                    if (!charName || charName === "{{char}}") return text;
                    const regex = new RegExp(charName, 'gi');
                    return text.replace(regex, `<span class="st-char-highlight">${charName}</span>`);
                }

                container.querySelector('.st-val-time').innerHTML = data.time;
                container.querySelector('.st-val-location').innerHTML = data.location;
                container.querySelector('.st-val-present').innerHTML = highlightChar(data.present);
                container.querySelector('.st-val-interaction').innerHTML = highlightChar(data.interaction);
                container.querySelector('.st-val-event').innerHTML = data.event;

                const card = container.querySelector('.st-summary-glass-card');
                card.addEventListener('click', function() {
                    this.classList.toggle('expanded');
                });
            })();
        </script>
    </div>
</body>
</html>
