<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <link href="https://fonts.googleapis.com/css2?family=VT323&display=swap" rel="stylesheet">
</head>
<body>
    <style>
        /* 作用域隔离，统一样式盒子 */
        .st-opt-wrapper {
            width: 100%;
            margin: 10px 0 25px 0;
            box-sizing: border-box;
            animation: stOptSlideFadeIn 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
            opacity: 0;
            transform: translateY(-10px);
            transition: all 0.3s ease;
        }

        @keyframes stOptSlideFadeIn {
            0% { opacity: 0; transform: translateY(-10px); }
            100% { opacity: 1; transform: translateY(0); }
        }

        /* 顶部工具栏基础结构 */
        .st-opt-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 10px 16px;
            font-size: 14px;
        }

        /* 切换按钮区 */
        .st-opt-themes {
            display: flex;
            gap: 10px;
            align-items: center;
        }

        .st-theme-dot {
            width: 14px;
            height: 14px;
            border-radius: 50%;
            cursor: pointer;
            transition: transform 0.2s, box-shadow 0.2s;
            box-sizing: border-box;
        }
        .st-theme-dot:hover { transform: scale(1.15); }
        .st-theme-dot.active { transform: scale(1.1); box-shadow: 0 0 0 2px var(--SmartThemeBodyColor, #888) inset; }

        .dot-minimal { background: #d0d0d0; }
        .dot-vintage { background: #234c7c; border: 2px solid #f7eed6; box-shadow: 0 0 0 1px #234c7c; }
        .dot-pixel { background: #000; border: 2px solid #fff; }
        .dot-pixel.active { box-shadow: 0 0 5px #fff; }

        /* 选项列表区基础结构 (解决对齐问题的核心) */
        .st-opt-body {
            display: flex;
            flex-direction: column;
        }

        .st-opt-row {
            display: flex;
            align-items: flex-start; /* 严格顶部对齐 */
            padding: 14px 16px;
            gap: 12px;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
        }

        /* 字母与正文的行高严格一致，杜绝错位 */
        .st-opt-letter {
            flex-shrink: 0;
            width: 24px;
            text-align: center;
            line-height: 1.6;
            font-size: 16px;
        }

        .st-opt-text {
            flex-grow: 1;
            line-height: 1.6;
            white-space: pre-wrap;
            word-break: break-word;
        }

        /* ================= 风格一：简约宋体艺术字 (Minimal Song) ================= */
        .theme-minimal {
            font-family: 'SimSun', 'STSong', 'Songti SC', serif; /* 宋体 */
            background: transparent;
            border-top: 1px solid rgba(150,150,150,0.2);
            border-bottom: 1px solid rgba(150,150,150,0.2);
        }
        .theme-minimal .st-opt-header {
            color: rgba(100,100,100,0.9);
            font-family: 'Xingkai SC', 'STXingkai', 'LiSu', 'Kaiti', serif; /* 艺术字：行楷/隶书 */
            font-size: 20px;
            letter-spacing: 4px;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.1);
        }
        .theme-minimal .st-opt-row { border-bottom: 1px dashed rgba(150,150,150,0.15); }
        .theme-minimal .st-opt-row:last-child { border-bottom: none; }
        .theme-minimal .st-opt-row:hover { background: rgba(150,150,150,0.05); }
        .theme-minimal .st-opt-letter { color: rgba(150,150,150,0.5); font-style: italic; font-family: Georgia, serif; }
        .theme-minimal .st-opt-text { color: var(--SmartThemeBodyColor, #666); font-size: 14.5px; opacity: 0.9; }


        /* ================= 风格二：复古海报 (Vintage) ================= */
        .theme-vintage {
            background-color: #f7eed6;
            border: 2px solid #234c7c;
            box-shadow: 6px 6px 0px #dca74e;
            border-radius: 2px;
        }
        .theme-vintage .st-opt-header {
            border-bottom: 2px solid #234c7c;
            color: #234c7c;
            font-family: 'KaiTi', 'STKaiti', 'BiauKai', serif;
            font-weight: bold;
            letter-spacing: 1px;
        }
        .theme-vintage .st-opt-row { border-bottom: 1px solid rgba(35, 76, 124, 0.2); }
        .theme-vintage .st-opt-row:last-child { border-bottom: none; }
        .theme-vintage .st-opt-letter { color: #234c7c; font-family: 'Georgia', serif; font-weight: bold; }
        .theme-vintage .st-opt-text { color: #234c7c; font-family: 'KaiTi', 'STKaiti', 'BiauKai', serif; font-size: 16px; font-weight: 600; }
        .theme-vintage .st-opt-row:hover { background-color: #234c7c; }
        .theme-vintage .st-opt-row:hover .st-opt-letter,
        .theme-vintage .st-opt-row:hover .st-opt-text { color: #f7eed6; }


        /* ================= 风格三：黑夜像素 (Pixel Night) ================= */
        .theme-pixel {
            background-color: #050505;
            border: 2px solid #fff;
            box-shadow: 0 0 10px rgba(255,255,255,0.1);
        }
        .theme-pixel .st-opt-header {
            border-bottom: 2px dashed #fff;
            color: #fff;
            font-family: 'VT323', monospace;
            font-size: 18px;
            letter-spacing: 2px;
            text-transform: uppercase;
        }
        .theme-pixel .st-opt-row {
            border-bottom: 1px dashed #444;
            padding-left: 28px; /* 为左侧RPG光标腾出空间 */
        }
        .theme-pixel .st-opt-row:last-child { border-bottom: none; }

        /* 增加 RPG 游戏经典的光标悬停效果，替代刺眼的大面积纯白 */
        .theme-pixel .st-opt-row::before {
            content: '>';
            position: absolute;
            left: 10px;
            color: #fff;
            font-family: 'VT323', monospace;
            font-size: 20px;
            line-height: 1.6;
            opacity: 0;
            transition: opacity 0.1s;
        }

        .theme-pixel .st-opt-letter {
            color: #888; /* 默认稍微暗一点 */
            font-family: 'VT323', monospace;
            font-size: 20px;
        }
        .theme-pixel .st-opt-text {
            color: #bbb;
            font-family: 'SimSun', '宋体', monospace;
            -webkit-font-smoothing: none;
            font-smooth: never;
            font-size: 14px;
        }
        .theme-pixel .st-opt-row:hover {
            background-color: #111; /* 极轻微的深灰背景提亮，不刺眼 */
        }
        .theme-pixel .st-opt-row:hover::before {
            opacity: 1; /* 显示光标 */
        }
        .theme-pixel .st-opt-row:hover .st-opt-letter,
        .theme-pixel .st-opt-row:hover .st-opt-text {
            color: #fff; /* 文字变纯白高亮 */
        }


        /* 点击反馈动画 */
        .st-opt-row.clicked::after {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(128, 128, 128, 0.4);
            animation: stFlash 0.3s ease-out forwards;
            pointer-events: none;
        }
        @keyframes stFlash { 0% { opacity: 1; } 100% { opacity: 0; } }
    </style>

    <!-- 容器 -->
    <div class="st-opt-wrapper" id="st-opt-container">
        <!-- 头部工具栏 -->
        <div class="st-opt-header">
            <div class="st-opt-title" id="st-opt-title-text">ACTION OPTIONS</div>
            <div class="st-opt-themes">
                <div class="st-theme-dot dot-minimal" data-theme="theme-minimal" title="宋体艺术字"></div>
                <div class="st-theme-dot dot-vintage" data-theme="theme-vintage" title="复古楷体"></div>
                <div class="st-theme-dot dot-pixel" data-theme="theme-pixel" title="黑夜像素"></div>
            </div>
        </div>

        <!-- 选项列表区 -->
        <div class="st-opt-body">
            <!-- A~D: 用户行为 -->
            <div class="st-opt-row" data-text="$1">
                <div class="st-opt-letter">A</div>
                <div class="st-opt-text">$1</div>
            </div>
            <div class="st-opt-row" data-text="$2">
                <div class="st-opt-letter">B</div>
                <div class="st-opt-text">$2</div>
            </div>
            <div class="st-opt-row" data-text="$3">
                <div class="st-opt-letter">C</div>
                <div class="st-opt-text">$3</div>
            </div>
            <div class="st-opt-row" data-text="$4">
                <div class="st-opt-letter">D</div>
                <div class="st-opt-text">$4</div>
            </div>
            <!-- E: 角色行为 -->
            <div class="st-opt-row" data-text="$5">
                <div class="st-opt-letter" style="opacity: 0.6;">E</div>
                <div class="st-opt-text">$5</div>
            </div>
            <!-- F: 时间跳过 -->
            <div class="st-opt-row" data-text="$6">
                <div class="st-opt-letter" style="opacity: 0.4;">F</div>
                <div class="st-opt-text">$6</div>
            </div>
        </div>
    </div>

    <script>
        (function() {
            const currentScript = document.currentScript;
            const wrapper = currentScript.previousElementSibling;
            const titleEl = wrapper.querySelector('#st-opt-title-text');

            // 动态修改标题文本以契合不同风格
            const updateTitleText = (theme) => {
                if (theme === 'theme-vintage') titleEl.innerText = '行动指引';
                else if (theme === 'theme-minimal') titleEl.innerText = '行 动 选 项'; // 艺术字中文
                else titleEl.innerText = 'SELECT ACTION';
            };

            // 1. 同步读取并应用主题
            const savedTheme = localStorage.getItem('st_opt_theme') || 'theme-vintage';
            wrapper.classList.add(savedTheme);
            updateTitleText(savedTheme);

            const themeDots = wrapper.querySelectorAll('.st-theme-dot');
            themeDots.forEach(dot => {
                if(dot.dataset.theme === savedTheme) dot.classList.add('active');

                // 绑定切换事件
                dot.addEventListener('click', (e) => {
                    const theme = e.target.dataset.theme;
                    wrapper.classList.remove('theme-minimal', 'theme-vintage', 'theme-pixel');
                    wrapper.classList.add(theme);
                    updateTitleText(theme);

                    themeDots.forEach(d => d.classList.remove('active'));
                    e.target.classList.add('active');
                    localStorage.setItem('st_opt_theme', theme);
                });
            });

            // 文本转义函数
            const escapeForST = (str) => {
                if (typeof str !== 'string') return str;
                return str.replace(/(\\+)?([|{}])/g, (m, s, c) => (s || '') + (s || '') + '\\' + c);
            };

            // 2. 点击填入输入框逻辑
            const optRows = wrapper.querySelectorAll('.st-opt-row');
            optRows.forEach(row => {
                row.addEventListener('click', () => {
                    if (typeof triggerSlash !== 'function') return;

                    // 视觉反馈动画
                    row.classList.remove('clicked');
                    void row.offsetWidth; // 触发重绘
                    row.classList.add('clicked');

                    // 获取并清洗文本
                    let rawText = row.getAttribute('data-text') || '';
                    const safeText = escapeForST(rawText);

                    // 发送命令
                    triggerSlash(`/setinput ${safeText}`);
                });
            });
        })();
    </script>
