            var val = parseInt(raw) || 0;
            if (val < 1) val = 1;
            if (val > 10) val = 10;

            /* 设置宽度 */
            fillBar.style.width = (val * 10) + '%';

            /* 根据强度值设置渐变颜色 */
            if (val <= 3) {
                /* 低强度：冷紫色 */
                fillBar.style.background = 'linear-gradient(90deg, #6a5acd, #9370db)';
            } else if (val <= 6) {
