                    && line.indexOf('轮次') === -1
                    && line.indexOf('阶段') === -1) {
                    /* 按 | 分割并去掉首尾空元素 */
                    var cells = line.split('|');
                    var cleaned = [];
                    for (var j = 0; j < cells.length; j++) {
                        var c = cells[j].trim();
                        if (c !== '' || (j > 0 && j < cells.length - 1)) {
                            if (j > 0 && j < cells.length - 1) cleaned.push(c);
                        }
                    }
                    if (cleaned.length >= 2) dataLines.push(cleaned);
                }
            }

            if (dataLines.length > 0) {
                /* 构建表格 */
                var headers = ['轮', '阶段', '姿势', '位置', '主动方', '被动方', 'Play', '强度'];
