                html += '</tr></thead><tbody>';
                for (var r = 0; r < dataLines.length; r++) {
                    html += '<tr>';
                    for (var c = 0; c < 8; c++) {
                        html += '<td>' + (dataLines[r][c] || '') + '</td>';
                    }
                    html += '</tr>';
                }
                html += '</tbody></table>';
                tableWrap.insertAdjacentHTML('beforeend', html);
            } else {
                tableWrap.insertAdjacentHTML('beforeend',
                    '<div class="sexlog-history-empty">暂无记录</div>');
            }
        }
