    <script>
    (function() {
        /* 获取当前脚本所在位置，向上查找最近的 .sexlog-panel 容器 */
        var script = document.currentScript;
        var panel = script.previousElementSibling;
        if (!panel || !panel.classList.contains('sexlog-panel')) {
            panel = script.parentElement.querySelector('.sexlog-panel:last-of-type');
        }
        if (!panel) return;

        /* ── 1. 处理强度条 ── */
        var fillBar = panel.querySelector('.sexlog-intensity-fill');
        if (fillBar) {
            var raw = fillBar.getAttribute('data-intensity');
            var val = parseInt(raw) || 0;
            if (val < 1) val = 1;
            if (val > 10) val = 10;

            /* 设置宽度 */
            fillBar.style.width = (val * 10) + '%';

            /* 根据强度值设置渐变颜色 */
            if (val <= 3) {
                /* 低强度：冷紫色 */
                fillBar.style.background = 'linear-gradient(90deg, #6a5acd, #9370db)';
            } else if (val <= 6) {
                /* 中强度：玫瑰粉 */
                fillBar.style.background = 'linear-gradient(90deg, #c06090, #e8a0bf)';
            } else {
                /* 高强度：火焰红 */
                fillBar.style.background = 'linear-gradient(90deg, #d03050, #ff6b81)';
            }

            /* 高强度时加快脉动频率 */
            if (val >= 8) {
                fillBar.style.animationDuration = '1.2s';
            } else if (val >= 5) {
                fillBar.style.animationDuration = '2s';
            }

            /* 同步心跳图标速度 */
            var heartIcon = panel.querySelector('.sexlog-heart-icon');
            if (heartIcon) {
                if (val >= 8) heartIcon.style.animationDuration = '0.8s';
                else if (val >= 5) heartIcon.style.animationDuration = '1.2s';
            }
        }

        /* ── 2. 解析并渲染历史记录表格 ── */
        var rawEl = panel.querySelector('.sexlog-raw-data');
        var tableWrap = panel.querySelector('.sexlog-history-table-wrap');
        if (rawEl && tableWrap) {
            var text = rawEl.textContent || '';
            var lines = text.split('\n');

            /* 过滤出有效数据行：以|开头，且不含表头关键字和分隔线 */
            var dataLines = [];
            for (var i = 0; i < lines.length; i++) {
                var line = lines[i].trim();
                if (line.indexOf('|') === 0
                    && line.indexOf('---') === -1
                    && line.indexOf('轮次') === -1
                    && line.indexOf('阶段') === -1) {
                    /* 按 | 分割并去掉首尾空元素 */
                    var cells = line.split('|');
                    var cleaned = [];
                    for (var j = 0; j < cells.length; j++) {
                        var c = cells[j].trim();
                        if (c !== '' || (j > 0 && j < cells.length - 1)) {
                            if (j > 0 && j < cells.length - 1) cleaned.push(c);
                        }
                    }
                    if (cleaned.length >= 2) dataLines.push(cleaned);
                }
            }

            if (dataLines.length > 0) {
                /* 构建表格 */
                var headers = ['轮', '阶段', '姿势', '位置', '主动方', '被动方', 'Play', '强度'];
                var html = '<table><thead><tr>';
                for (var h = 0; h < headers.length; h++) {
                    html += '<th>' + headers[h] + '</th>';
                }
                html += '</tr></thead><tbody>';
                for (var r = 0; r < dataLines.length; r++) {
                    html += '<tr>';
                    for (var c = 0; c < 8; c++) {
                        html += '<td>' + (dataLines[r][c] || '') + '</td>';
                    }
                    html += '</tr>';
                }
                html += '</tbody></table>';
                tableWrap.insertAdjacentHTML('beforeend', html);
            } else {
                tableWrap.insertAdjacentHTML('beforeend',
                    '<div class="sexlog-history-empty">暂无记录</div>');
            }
        }
    })();
    </script>
