    <style>
        /* 引入你指定的字体 */
        @import url("https://fontsapi.zeoseven.com/2/main/result.css");

        /* 定义亮色和暗色主题的颜色变量 */
        :root {
            --font-main: "LXGW ZhenKai GB", "Microsoft YaHei", sans-serif;
