        /* 深色主题（默认） */
        body.theme-dark {
            --bg-color: transparent;
            --text-color: #e0e5f0;
            --text-color-subtle: rgba(224, 229, 240, 0.4);
            --border-color: rgba(224, 229, 240, 0.3);
            --hover-bg-color: rgba(255, 255, 255, 0.1);
            --selected-indicator: '🐾';
            --theme-icon: '☀️';
        }

        /* 浅色主题 */
        body.theme-light {
            --bg-color: transparent;
            --text-color: #3d3d3d;
            --text-color-subtle: rgba(61, 61, 61, 0.5);
            --border-color: rgba(61, 61, 61, 0.3);
            --hover-bg-color: rgba(0, 0, 0, 0.05);
            --selected-indicator: '✒️';
            --theme-icon: '🌙';
        }

        body {
            font-family: var(--font-main);
            font-weight: normal;
            color: var(--text-color);
            line-height: 1.4;
            margin: 0;
            padding: 0;
            background: var(--bg-color) !important;
            opacity: 0.9;
            max-width: 100%;
            transition: color 0.3s ease, background-color 0.3s ease;
        }

        .branch-selector {
            max-width: 100%;
            margin: 2px 0;
            opacity: 1;
        }

        .collapsible-container {
            display: block;
            border: none;
            width: 100%;
