        .summary-text {
            list-style: none;
            cursor: pointer;
            padding: 1px 0;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.95em;
            opacity: 0.9;
        }

        /* 头部和切换主题的按钮容器 */
        .header-content {
            display: flex;
            align-items: center;
            gap: 8px; /* 增加间隙 */
        }

        /* 切换主题按钮样式 */
        #theme-toggle {
            background: none;
            border: none;
            cursor: pointer;
            font-size: 1.1em;
            padding: 0 4px;
            opacity: 0.6;
            transition: opacity 0.3s ease;
        }
        #theme-toggle:hover {
            opacity: 1;
        }
        #theme-toggle::before {
            content: var(--theme-icon);
        }

        .content-wrapper {
            padding: 4px 0 4px 8px;
            border-left: 1px dotted var(--border-color);
            margin-left: 4px;
            opacity: 0.9;
            transition: border-color 0.3s ease;
        }

        #options-container {
            padding: 0;
            margin: 0;
            list-style-type: none;
        }

        .clickable-text {
            cursor: pointer;
            padding: 4px 8px 4px 28px;
            margin-bottom: 2px;
            border-radius: 4px;
            font-size: 0.9em;
            transition: background-color 0.15s ease, opacity 0.15s ease;
            opacity: 0.85;
            position: relative;
            color: var(--text-color);
        }

        .clickable-text:hover {
            background-color: var(--hover-bg-color);
            opacity: 1;
        }

        .clickable-text li {
            list-style: none;
            position: relative;
            padding-left: 0;
            margin-left: 0;
            transition: font-weight 0.3s ease;
        }

        .clickable-text.selected li {
            font-weight: bold;
            opacity: 1;
        }

        /* 选中项的前置图标 */
        .clickable-text::before {
            content: '';
